  const text=String(renderer.text??renderer.lastText??'');let base=0;if(text!==fullText){const offset=fullText.indexOf(text);if(offset<0)throw Error('Cannot map source lines to embedded section');base=fullText.slice(0,offset).split('\n').length-1;}
  const local=line-1-base;const section=renderer.sections.find((s:any)=>s.start?.line<=local&&s.end?.line>=local);if(!section)throw Error('Source line not rendered in this embed');
  renderer.showSection?.(section);renderer.applyScrollSection?.(section);renderer.updateVirtualDisplay?.();await delay(80);
  const el=section.el as HTMLElement;if(!el?.isConnected)throw Error('Section not mounted');
